<script setup lang="ts">
import {formatUsageTokens as token} from '../../utils/usageTokenFormat'
import {useUsageText} from '../../composables/useUsageText'
const tr=useUsageText()
import {computed,ref,watch,onBeforeUnmount} from 'vue'
const p=defineProps<{series:any[];mode?:'tokens'|'calls'}>();defineEmits(['select'])
const max=computed(()=>Math.max(1,...p.series.flatMap(b=>p.mode==='calls'?['tools','mcp','skills'].map(k=>Number(b[k]??0)):[Number(b.total??0)])))
const chart=ref<HTMLElement|null>(null),chartWidth=ref(300);let observer:ResizeObserver|undefined;watch(chart,el=>{observer?.disconnect();if(el&&typeof ResizeObserver!=='undefined'){observer=new ResizeObserver(()=>chartWidth.value=el.clientWidth);observer.observe(el)}});onBeforeUnmount(()=>observer?.disconnect())
const keys=['tools','mcp','skills'];const lineColors=['#58a6ff','#16805e','#d29922'];const ticks=computed(()=>[max.value,Math.round(max.value/2),0]);const x=(i:number)=>p.series.length===1?50:i/(p.series.length-1)*100;const y=(b:any,k:string)=>95-Number(b[k])/max.value*90
const paths=computed(()=>['tools','mcp','skills'].map(k=>{let open=false;return p.series.map((b,i)=>{if(b[k]===null){open=false;return ''}const c=`${p.series.length===1?50:i/(p.series.length-1)*100},${95-Number(b[k])/max.value*90}`;const s=(open?'L':'M')+c;open=true;return s}).join(' ')}))
</script>
<template><div v-if="mode==='calls'" class="pu-line-layout"><div class="pu-axis"><small>{{tr('次数')}}</small><span v-for="(t,i) in ticks" :key="i">{{t.toLocaleString()}}</span></div><div ref="chart" class="pu-line-chart"><svg viewBox="0 0 100 100" preserveAspectRatio="none" :aria-label="tr('工具 MCP Skill 三条次数趋势')"><path v-for="(path,i) in paths" :key="i" :d="path" fill="none" :stroke="['#58a6ff','#16805e','#d29922'][i]" :stroke-dasharray="['','3 2','1 2'][i]" stroke-width="1" /><g v-for="(k,i) in keys" :key="k"><template v-for="(b,j) in series" :key="j"><ellipse v-if="b[k]!==null && b[k]!==undefined" :cx="x(j)" :cy="y(b,k)" :rx="250/chartWidth" ry="1.39" :fill="lineColors[i]" vector-effect="non-scaling-stroke"/></template></g></svg><div class="pu-call-points"><button v-for="b in series" :key="b.bucket_start" :aria-label="`${b.bucket_start}: ${tr('工具调用')}${b.tools??tr('未采集')} MCP${b.mcp??tr('未采集')} Skill${b.skills??tr('未采集')}`" :title="`${b.bucket_start}: ${tr('工具调用')}${b.tools??tr('未采集')} MCP${b.mcp??tr('未采集')} Skill${b.skills??tr('未采集')}`" @click="$emit('select',b,$event)">·</button></div></div></div><div v-else class="pu-chart pu-stacked"><button v-for="b in series" :key="b.bucket_start" class="pu-day" :aria-label="`${b.bucket_start.slice(0,10)}: ${b.total===null?tr('未采集'):token(b.total)}`" @click="$emit('select',b,$event)"><span v-if="b.total!==null" class="pu-stack" :style="{height:Math.max(2,Number(b.total)/max*95)+'%'}"><i v-for="k in ['cache_create','cache_read','output','input']" :key="k" class="pu-bar" :class="k.includes('cache')?'cache':k" :style="{height: Number(b.total)?Number(b[k]??0)/Number(b.total)*100+'%':'0'}"/><i v-if="b.input===null" class="pu-bar" style="height:100%;background:var(--muted)"/></span><span v-else class="pu-gap">—</span></button></div><div class="pu-chartlabels"><span>{{series[0]?.bucket_start.slice(0,10)}}</span><span>{{series.at(-1)?.end_exclusive.slice(0,10)}} · UTC</span></div><div class="pu-legend"><template v-if="mode==='calls'"><span v-for="(label,i) in ['工具调用','MCP（已含在工具中）','Skill（独立）']" :key="label"><svg width="24" height="8"><path d="M0 4H24" :stroke="lineColors[i]" :stroke-dasharray="['','5 3','2 3'][i]" stroke-width="2"/></svg> {{tr(label)}}</span></template><template v-else>{{tr('输入 · 输出 · 缓存 · 未确认构成')}}</template><span>{{tr('缺口不补零')}}</span></div></template>
<style scoped>.pu-line-layout{display:grid;grid-template-columns:45px minmax(0,1fr);gap:8px}.pu-axis{height:180px;display:flex;flex-direction:column;justify-content:space-between;color:var(--muted);font-size:10px;position:relative;padding:8px 0}.pu-axis small{position:absolute;top:-16px}.pu-legend span{display:inline-flex;align-items:center;gap:3px}.pu-line-chart{background:repeating-linear-gradient(to top,transparent 0,transparent 88px,var(--line) 89px,transparent 90px)}.pu-line-chart{height:180px;position:relative}.pu-call-points{position:absolute;inset:0;display:flex}.pu-call-points button{flex:1;min-width:0;background:transparent;border:0;color:transparent}.pu-call-points button:hover,.pu-call-points button:focus-visible{background:color-mix(in srgb,var(--accent) 10%,transparent)}.pu-line-chart svg{width:100%;height:100%;overflow:visible}.pu-gap{align-self:center;color:var(--muted)}</style>
